            MD_CHECK_CC( ( metric->SetSnapshotReportReadEquation( "dw@0xcc 2 dw@0xfc UMUL UADD 4 dw@0xf8 UMUL UADD 8 dw@0xf4 UMUL UADD 16 dw@0xf0 UMUL UADD 32 dw@0xec UMUL UADD 64 dw@0xe8 UMUL UADD" ) ) );
            MD_CHECK_CC( ( metric->SetDeltaReportReadEquation( "qw@0x158 2 qw@0x1b8 UMUL UADD 4 qw@0x1b0 UMUL UADD 8 qw@0x1a8 UMUL UADD 16 qw@0x1a0 UMUL UADD 32 qw@0x198 UMUL UADD 64 qw@0x190 UMUL UADD" ) ) );
            MD_CHECK_CC( ( metric->SetSnapshotReportDeltaFunction( "DELTA 32" ) ) );
